# Staff7 legislator page (R-398 piece 14), on the practice copy: strip, contact bar, Yours | Whole team, Now with them, Our bills, Notes at the foot (the card: Follow up, Good to know, Cares about, Our contact, Where they stand; then the Log with Show all and its filter), stance with Undo, Log a talk with a Kind and Undo, no old sections, no sideways scroll at 1440, 1280, 390 and 320.
#   python3 tests/staff7_leg_page.py [base] [shots folder]     base defaults to http://127.0.0.1:8876
import sys, os, re
from playwright.sync_api import sync_playwright
BASE = (sys.argv[1] if len(sys.argv) > 1 else 'http://127.0.0.1:8876').rstrip('/')
SHOTS = sys.argv[2] if len(sys.argv) > 2 else ''
if SHOTS: os.makedirs(SHOTS, exist_ok=True)
res = []
def ok(c, m): res.append(bool(c)); print('PASS' if c else 'FAIL', m)
SIDE = "() => document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth"
def open_as(br, w, h, who='KV', hash='#/more/legislators/130', style=None):   # style: a page style left in the tab's storage by an earlier build (the page must ignore it)
    ctx = br.new_context(viewport={'width': w, 'height': h}); pg = ctx.new_page(); pg.errs = []
    pg.on('pageerror', lambda e: pg.errs.append(str(e)))
    pg.on('console', lambda m: pg.errs.append(m.text) if m.type == 'error' and 'Failed to load resource' not in m.text and 'ERR_FAILED' not in m.text else None)
    if style: pg.add_init_script(f"try{{if(!sessionStorage.getItem('lp.style'))sessionStorage.setItem('lp.style','{style}')}}catch(e){{}}")
    pg.goto(f'{BASE}/staff7.html?demo=1&as={who}{hash}'); pg.wait_for_selector('#lgPageBody #lpMain h2', state='attached', timeout=60000)
    pg.evaluate("Promise.all([document.fonts.load('600 16px Poppins'), document.fonts.load('400 16px Lato')])"); pg.wait_for_timeout(400)
    return pg
def snap(pg, name):
    if SHOTS: pg.screenshot(path=os.path.join(SHOTS, name))
def txt(pg, sel='#lpMain'): return pg.inner_text(sel)
def h2s(pg): return pg.eval_on_selector_all('#lpMain h2', "els => els.map(e => e.innerText.replace(/\\s+/g,' ').trim())")
def bills_n(pg): return pg.locator('#lpMain .lpbr').count()

with sync_playwright() as p:
    br = p.chromium.launch()
    pg = open_as(br, 1440, 900, 'KV')
    ok(pg.inner_text('h1').strip() == 'Gregg Takayama' and 'Representative · Democrat · District 34' in txt(pg, '.lpstrip'), f'strip: name and chamber · party · district')
    ok(txt(pg, '.lpstrip').count('Log a talk') >= 1 and pg.locator('.btn.filled:visible').count() == 1, f'Log a talk is the only filled button ({pg.locator(".btn.filled:visible").count()})')
    ok(pg.locator('a[href^="tel:"]:visible').first.get_attribute('href') == 'tel:808-586-6340' and pg.locator('.lpa[href="mailto:reptakayama@capitol.hawaii.gov"]:visible').count() == 1 and 'Room 404' in txt(pg, '.lpbar'), f'Call tel:, Email mailto:, Room')
    ok('Capitol’s records' in txt(pg, '.lpstrip'), f'source line')
    hs = h2s(pg); order = [next((i for i, h in enumerate(hs) if h.startswith(k)), -1) for k in ('Now with Takayama', 'Our bills with them', 'Notes')]
    ok(order == sorted(order) and -1 not in order, f'one column, sections in order Now with, Our bills, Notes ({hs})')
    ok(pg.locator('h1').count() == 1, f'one h1 ({pg.locator("h1").count()})')
    body = pg.inner_text('body')
    ok(not any(k in body for k in ('Latest talk', 'What they said to our asks', 'Testimony we sent them', 'About them')), 'no old section headings anywhere')
    ok(pg.eval_on_selector_all('#lpMain .ln h3', "els => els.map(e => e.innerText.replace(/\\s+/g,' ').trim())")[0].startswith('Log'), 'Log is a heading after Notes')
    rows = pg.eval_on_selector_all('.ln .ln-k', "els => els.map(e => e.innerText.trim())")
    ok(rows == ['Follow up', 'Good to know', 'Cares about', 'Our contact', 'Where they stand'], f'card rows in order for Takayama ({rows})')
    fu = pg.eval_on_selector_all('.ln-row:has(.ln-k:text-is("Follow up")) .ln-v p', "els => els.map(e => e.innerText.replace(/\\s+/g,' ').trim())")
    ok(len(fu) == 2 and fu[0].startswith('You ·') and not fu[1].startswith('You') and 'Follow up' in fu[1], f'Follow up: two, yours first ({fu})')
    ok('Log a talk' in fu[0] and 'Log a talk' not in fu[1], 'Follow up: Log a talk link on yours only')
    ok(pg.locator('.ln-row:has(.ln-k:text-is("Good to know")) li').count() == 2, 'Good to know: two lines')
    ok(re.search(r'\w+ · \w{3} \d+, \d{4} · Remove', pg.inner_text('.ln-row:has(.ln-k:text-is("Good to know")) li').replace('\n', ' ')) is not None or 'Remove' in pg.inner_text('.ln-row:has(.ln-k:text-is("Good to know")) li').replace('\n', ' '), 'Good to know: writer, date and Remove on each line')
    ok('Not known on any bill yet' in txt(pg, '.ln-row:has(.ln-k:text-is("Where they stand"))') and 'Set on a bill' in txt(pg, '.ln'), 'Where they stand: none known yet, with Set on a bill')
    ok('not known on' not in txt(pg, '.ln').lower().replace('not known on any', ''), 'no "not known on N others" count')
    ok(pg.locator('.ln-now').count() == 0 and pg.locator('#lpMain button:has(> b)').count() == 0, 'no Now pointer line anywhere')
    ok(pg.evaluate("() => [...document.querySelectorAll('#lpMain h1,#lpMain h2,#lpMain h3,#lpMain b,#lpMain button')].filter(e => e.textContent.trim().startsWith('Now')).map(e => e.textContent.trim()).join('|')") == 'Now with Takayama', 'the word Now appears only as the heading Now with Takayama')
    ok(pg.evaluate("() => document.querySelector('#lpMain .lpcol').firstElementChild.classList.contains('lpsw') && document.querySelector('.lpsw').nextElementSibling.querySelector('#lpNowH') !== null"), 'the switch is first in the column and Now with comes right under it')
    ok(pg.evaluate("() => { const n = document.getElementById('lpNowH').getBoundingClientRect(), t = document.querySelector('.ln').getBoundingClientRect(), b = document.getElementById('lpBillsH').getBoundingClientRect(); return n.top < b.top && b.top < t.top; }"), '1440: Notes sits after Our bills (Now above bills above Notes)')
    ok(pg.evaluate("() => { const t = document.getElementById('lpNotesH').getBoundingClientRect(), bs = document.querySelector('.lpsec:has(#lpBillsH)').getBoundingClientRect(), b = document.getElementById('lpBillsH').getBoundingClientRect(), nw = document.querySelector('.lpsec:has(#lpNowH)').getBoundingClientRect(); return b.top - nw.bottom >= 24 && t.top - bs.bottom >= 24; }"), '1440: 24px or more between Now with, Our bills and Notes')
    pg.click('.ln [data-act=goto]'); pg.wait_for_timeout(200)
    ok(pg.evaluate("document.activeElement && document.activeElement.id") == 'lpBillsH', 'Set on a bill: moves focus to the Our bills heading')
    # the Log
    ok(pg.locator('.ln-tl > li').count() == 3, f'Log shows the last 3 ({pg.locator(".ln-tl > li").count()})')
    nlog = int(re.search(r'Log\s*·\s*(\d+)', pg.inner_text('#lpMain .ln h3')).group(1)); sa = pg.locator('.ln-more [data-act=all]')
    ok(sa.inner_text().strip() == f'Show all {nlog}' and nlog > 3 and pg.locator('[data-lf]').count() == 0, f'Show all {nlog}, no filter yet')
    sa.click(); pg.wait_for_timeout(150)
    ok(pg.locator('.ln-tl > li').count() == nlog and pg.locator('[data-lf]').count() == 4 and pg.evaluate("document.activeElement.dataset.act") == 'all', f'Show all opens every entry ({pg.locator(".ln-tl > li").count()} of {nlog}), the filter appears, focus stays')
    ok(pg.locator('[data-lf="all"]').get_attribute('aria-pressed') == 'true', 'filter: All pressed')
    fl = pg.eval_on_selector_all('[data-lf]', "els => els.map(e => [e.dataset.lf, e.innerText.replace(/\\s+/g, ' ').trim(), getComputedStyle(e.querySelector('.ln-n')).color, getComputedStyle(e).color])")
    ok([x[1] for x in fl][0] == f'All {nlog}' and all(re.fullmatch(r'(Talks|Asks|Testimony) \d+', x[1]) for x in fl[1:]) and all(x[2] != fl[0][3] for x in fl), f'each filter choice shows its count in the muted colour ({[x[1] for x in fl]})')
    cnt = {}
    for k in ('talks', 'asks', 'testimony'):
        pg.click(f'[data-lf="{k}"]'); pg.wait_for_timeout(100)
        cnt[k] = pg.locator('.ln-tl > li').count()
        ok(cnt[k] == pg.locator(f'.ln-tl > li[data-g="{k}"]').count() > 0 and pg.get_attribute(f'[data-lf="{k}"]', 'aria-pressed') == 'true' and pg.evaluate("document.activeElement.dataset.lf") == k, f'filter {k}: {cnt[k]} entries, all of that kind, pressed, focus stays')
    ok(sum(cnt.values()) == nlog and cnt['talks'] >= 5, f'filter counts add up to Log · {nlog} ({cnt})')
    ok(all(x[1].endswith(' ' + str(cnt[x[0]])) for x in fl if x[0] != 'all'), f'the counts on the choices match the entries each shows ({cnt})')
    pg.click('[data-lf="all"]')
    qs = pg.locator('.ln-tl > li.ln-sm')
    ok(qs.count() == cnt['asks'] + cnt['testimony'] and qs.locator('.ln-bd').count() == 0 and pg.locator('.ln-tl > li[data-g="talks"] .ln-bd').count() == cnt['talks'], 'asks and testimony are quiet lines with no body; talks have one')
    ok(pg.locator('.ln-tl > li[data-g="talks"] .ln-hd').first.inner_text() != '' and all(re.match(r'(Call|Meeting|Email|In passing|Note) · ', x) for x in pg.eval_on_selector_all('.ln-tl > li[data-g="talks"] .ln-hd', "els => els.map(e => e.innerText.trim())")), 'talks lead with their kind in words')
    ok(pg.locator('.ln-tl > li[data-g="asks"]').first.inner_text().replace('\n', ' ').find('Asked for a hearing') >= 0 and pg.locator('.ln-tl > li[data-g="testimony"]').first.inner_text().replace('\n', ' ').find('Testimony sent') >= 0, 'ask and testimony entries read as asked and sent')
    pg.click('.ln-more [data-act=all]'); pg.wait_for_timeout(150)
    ok(pg.locator('.ln-tl > li').count() == 3 and pg.locator('[data-lf]').count() == 0 and pg.inner_text('.ln-more').strip() == f'Show all {nlog}', 'Show the last 3 folds the Log back')
    ok(pg.evaluate(SIDE), f'no sideways scroll at 1440')
    snap(pg, f'page_1440.png')
    ok(not pg.errs, f'no page error {pg.errs[:1]}')
    pg.context.close()

    # ---- A: switch, stance, Log a talk, staffer
    pg = open_as(br, 1440, 900, 'KR')
    OTHER = [i for i in pg.eval_on_selector_all('#legList .lgr', 'els => els.map(e => e.dataset.id)') if i != '130'][0]
    ys, ts = pg.evaluate("() => [...document.querySelectorAll('.lpsegs .seg')].map(b => +b.textContent.match(/(\\d+)/)[1])")
    n_y = bills_n(pg); LAT = '.ln'; latest0 = pg.inner_text(LAT)
    pg.click('.lpsegs [data-view=team]'); pg.wait_for_timeout(200)
    ok(pg.locator('#lpMain .lpwho').count() > 0 and 'Whole team' in pg.inner_text('.lpsegs [aria-current=true]'), 'switch: Whole team shows names, muted, first')
    ok(pg.locator('#lpMain .lpbr .lpwho').count() == pg.locator('#lpMain .lpbr').count() > 0, 'Whole team: a name on every bill row')
    ok(pg.inner_text(LAT) == latest0, 'switch does not change Notes')
    # open all groups: Whole team shows every group first folded
    for b in pg.locator('[data-fold]').all(): pass
    pg.click('.lpsegs [data-view=yours]'); pg.wait_for_timeout(200)
    ok(ys == 10 and ts >= ys and 'Chairs the committee' in txt(pg), f'Yours · {ys} and Whole team · {ts}')
    # Yours remembered between legislators (in the tab)
    pg.click('.lpsegs [data-view=team]'); pg.evaluate(f"location.hash = '#/more/legislators/{OTHER}'"); pg.wait_for_selector('#lpMain .lpsw', timeout=10000); pg.wait_for_timeout(300)
    ok('Whole team' in pg.inner_text('.lpsegs [aria-current=true]') or pg.locator('.lpsegs .seg[disabled]').count() == 1, 'the choice is remembered for the next legislator')
    pg.evaluate("location.hash = '#/more/legislators/130'"); pg.wait_for_selector('#lpMain .lpsw', timeout=10000); pg.wait_for_timeout(300)
    ok('Whole team' in pg.inner_text('.lpsegs [aria-current=true]'), 'remembered Whole team back on Takayama')
    pg.click('.lpsegs [data-view=yours]')
    # stance
    first = pg.locator('[data-stance]').first; bid = first.get_attribute('data-stance'); before = pg.inner_text(f'.lpbr:has([data-stance="{bid}"]) .lpsv')
    first.click(); pg.select_option('#lpSt', label='Leaning yes'); pg.wait_for_timeout(250)
    ok(pg.inner_text(f'.lpbr:has([data-stance="{bid}"]) .lpsv') == 'Leaning yes' and 'Saved: Leaning yes' in pg.inner_text('#toast'), 'stance: Set/Change, select, saved')
    ok(pg.locator('#toastUndo:visible').count() == 1, 'stance: Undo shown')
    pg.click('#toastUndo'); pg.wait_for_timeout(250)
    ok(pg.inner_text(f'.lpbr:has([data-stance="{bid}"]) .lpsv') == before, f'stance: Undo restores ({before})')
    # Log a talk
    FU = lambda: pg.locator('.ln-row:has(.ln-k:text-is("Follow up")) .ln-v p').count()
    LOG = lambda: pg.locator('.ln-tl > li').first.inner_text().replace('\n', ' ')
    fu0 = FU(); log0 = int(re.search(r'Log\s*·\s*(\d+)', pg.inner_text('#lpMain .ln h3')).group(1))
    ok(fu0 == 2 and pg.inner_text('.ln-row:has(.ln-k:text-is("Follow up")) .ln-v p').startswith('You'), f'KR: Follow up has two, hers first ({fu0})')
    pg.click('.ln-lt'); pg.wait_for_selector('#lpTalkForm', timeout=5000)
    ok(pg.evaluate("document.activeElement.id") == 'lpTalkBody', 'Follow up: Log a talk link opens the form')
    pg.click('#lpTalkCancel'); pg.wait_for_timeout(150)
    pg.click('#lpTalkBtn'); pg.wait_for_selector('#lpTalkForm', timeout=5000)
    ok('Write only what was said and their public role. Others on staff can read notes.' in pg.inner_text('#lpTalkForm') and 'Follow up by' in txt(pg, '#lpTalkForm') and 'It shows at the top of their notes until you log your next talk with them.' in txt(pg, '#lpTalkForm') and pg.inner_text('#lpTalkForm h2').startswith('Log a talk'), 'Log a talk: fields and hints')
    ok(re.search(r'\w{3}, \w{3} \d+', pg.inner_text('#lpTalkWhen')) is not None, f'Log a talk: date in words ({pg.inner_text("#lpTalkWhen")})')
    ok(pg.eval_on_selector('#lpTalkForm', "e => e.getBoundingClientRect().width") <= 681, 'Log a talk: form no wider than the 680px column')
    ok(pg.locator('#lpTalkForm .lpkind [data-kind]').count() == 4 and pg.eval_on_selector_all('#lpTalkForm .lpkind [data-kind]', "els => els.map(e => e.innerText.trim())") == ['Call', 'Meeting', 'Email', 'In passing'] and pg.locator('#lpTalkForm [data-kind][aria-pressed=true]').count() == 0, 'Kind row: Call, Meeting, Email, In passing, none chosen')
    ok(pg.eval_on_selector('#lpTalkForm', "e => e.querySelector('#lpKindL').compareDocumentPosition(e.querySelector('#lpTalkBody')) & 4") and 'optional' in pg.inner_text('#lpKindL'), 'Kind row comes first, marked optional')
    pg.click('[data-kind=call]'); ok(pg.get_attribute('[data-kind=call]', 'aria-pressed') == 'true', 'Kind: tap chooses')
    pg.click('[data-kind=call]'); ok(pg.locator('[data-kind][aria-pressed=true]').count() == 0, 'Kind: tap again clears')
    pg.click('[data-kind=email]'); pg.fill('#lpTalkBody', 'Spoke on the phone about the practice test.')
    # S-11: leaving keeps the words and the kind
    pg.evaluate(f"location.hash = '#/more/legislators/{OTHER}'"); pg.wait_for_timeout(400); pg.evaluate("location.hash = '#/more/legislators/130'"); pg.wait_for_selector('#lpTalkForm', timeout=5000)
    ok(pg.input_value('#lpTalkBody') == 'Spoke on the phone about the practice test.' and pg.get_attribute('[data-kind=email]', 'aria-pressed') == 'true', 'typed words and kind are kept when the person leaves and comes back')
    pg.click('#lpTalkSave'); pg.wait_for_timeout(300)
    ok('practice test' in LOG() and LOG().startswith(re.search(r'[A-Z][a-z]{2} \d+, \d{4}', LOG()).group(0)) and 'Email · You' in LOG() and pg.locator('#lpTalkForm').count() == 0, f'Save: tops the Log with its kind ({LOG()[:80]})')
    ok(int(re.search(r'Log\s*·\s*(\d+)', pg.inner_text('#lpMain .ln h3')).group(1)) == log0 + 1, 'Save: Log count goes up by one')
    ok(FU() == fu0 - 1 and not pg.inner_text('.ln-row:has(.ln-k:text-is("Follow up")) .ln-v').startswith('You'), f'Save: her earlier follow-up clears after her next talk ({FU()})')
    pg.click('#toastUndo'); pg.wait_for_timeout(300)
    ok('practice test' not in txt(pg) and FU() == fu0, 'Undo removes the talk and brings the follow-up back')
    pg.click('#lpTalkBtn'); pg.fill('#lpTalkBody', 'x'); pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
    ok(pg.locator('#lpTalkForm').count() == 0, 'Escape cancels')
    # a saved talk with a follow-up date shows in the card
    pg.click('#lpTalkBtn'); pg.click('[data-kind=meeting]'); pg.fill('#lpTalkBody', 'Met in the hallway about the practice test.')
    fud = pg.evaluate("() => { const e = document.getElementById('lpTalkFu'); const d = new Date(e.min + 'T12:00:00'); d.setDate(d.getDate() + 6); return d.toISOString().slice(0, 10); }")
    pg.fill('#lpTalkFu', fud); pg.click('#lpTalkSave'); pg.wait_for_timeout(300)
    ok('Meeting · You' in LOG() and 'practice test' in LOG() and FU() == fu0 and re.search(r'You · Follow up by', pg.inner_text('.ln-row:has(.ln-k:text-is("Follow up")) .ln-v p')) is not None, 'a new talk with a follow-up date: Meeting on the Log, its follow-up first in the card')
    pg.click('#toastUndo'); pg.wait_for_timeout(200)
    # Good to know: add, remove, Undo
    G = '.ln-row:has(.ln-k:text-is("Good to know"))'; g0 = pg.locator(f'{G} li').count()
    pg.click(f'{G} [data-act=add-line]'); ok(pg.evaluate("document.activeElement.id") == 'lpLine' and 'Others on staff can read this. Write only what helps the next talk.' in txt(pg, G) and pg.get_attribute('#lpLine', 'maxlength') == '200', 'Add a line: field in place, labelled, hint, 200 characters, focused')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
    ok(pg.locator('#lpLine').count() == 0 and pg.evaluate("document.activeElement.dataset.act") == 'add-line', 'Add a line: Escape cancels and focus returns to Add a line')
    pg.click(f'{G} [data-act=add-line]'); pg.fill('#lpLine', 'Likes short emails with one clear ask.'); pg.click('form[data-form=line] [type=submit]'); pg.wait_for_timeout(200)
    ok(pg.locator(f'{G} li').count() == g0 + 1 and 'Likes short emails' in pg.inner_text(f'{G} li >> nth=0') and pg.inner_text(f'{G} li >> nth=0').startswith('Likes') and 'You' in pg.inner_text(f'{G} li >> nth=0'), 'Add a line: saved first, by You')
    pg.click('#toastUndo'); pg.wait_for_timeout(200); ok(pg.locator(f'{G} li').count() == g0, 'Add a line: Undo')
    pg.click(f'{G} [data-act=pin-remove] >> nth=0'); pg.wait_for_timeout(200)
    ok(pg.locator(f'{G} li').count() == g0 - 1 and 'Removed' in pg.inner_text('#toast'), 'Remove: the line goes')
    pg.click('#toastUndo'); pg.wait_for_timeout(200); ok(pg.locator(f'{G} li').count() == g0, 'Remove: Undo brings it back')
    # Staffer popover, folded group
    pg.click('#lpStaffBtn'); ok(pg.locator('#lpStaffPop a[href^="tel:"]:visible').count() == 1 and pg.locator('#lpStaffPop a[href^="mailto:"]:visible').count() == 1 and pg.locator('#lpStaffPop [data-act=staff-edit]').count() == 1, 'staffer popover: phone, email, Edit')
    pg.click('#lpStaffPop [data-act=staff-edit]'); pg.fill('#lpSN', 'Pat Test'); pg.click('#lpStaffPop button[type=submit]'); pg.wait_for_timeout(200)
    ok('Staffer: Pat Test' in txt(pg, '.lpbar'), 'staffer edit saves in memory')
    pg.click('#toastUndo'); pg.wait_for_timeout(200); ok('Staffer: Alana Perreira' in txt(pg, '.lpbar'), 'staffer Undo')
    n0 = pg.locator('#lpMain .lpbr').count(); pg.locator('[data-fold]').first.click(); ok(pg.locator('#lpMain .lpbr').count() > n0, 'Show N opens a folded group')
    pg.click('[data-act=form-cares]'); ok(pg.evaluate("document.activeElement.id") == 'lpCareT', 'Cares about: Edit opens in its row, focused')
    pg.fill('#lpCareT', 'One, Two'); pg.click('form[data-form=cares] [type=submit]'); pg.wait_for_timeout(200)
    ok(pg.locator('.ln-tags li').count() == 2, 'what they care about: edit saves'); pg.click('#toastUndo'); pg.wait_for_timeout(200); ok(pg.locator('.ln-tags li').count() == 3, 'what they care about: Undo')
    pg.click('[data-act=form-contact]'); pg.select_option('#lpCt', label='Nate'); pg.click('form[data-form=contact] [type=submit]'); pg.wait_for_timeout(200)
    CT = txt(pg, '.ln-row:has(.ln-k:text-is("Our contact"))')
    ok('Nate keeps in touch' in CT or 'You keep in touch' in CT, f'Our contact: Change saves ({CT.strip()[:40]!r})')
    pg.click('#toastUndo'); pg.wait_for_timeout(200)
    ok('Kris keeps in touch' in txt(pg, '.ln-row:has(.ln-k:text-is("Our contact"))') or 'You keep in touch' in txt(pg, '.ln-row:has(.ln-k:text-is("Our contact"))') or 'keeps in touch' in txt(pg, '.ln-row:has(.ln-k:text-is("Our contact"))'), 'Our contact: Undo')
    # Where they stand lists a stance set below, and Set on a bill jumps
    pg.click('.ln [data-act=goto][data-to=lpBillsH]'); pg.wait_for_timeout(150)
    ok(pg.evaluate("document.activeElement.id") == 'lpBillsH', 'Set on a bill: moves focus to Our bills')
    sf = pg.locator('[data-stance]').first; sid = sf.get_attribute('data-stance'); sf.click(); pg.select_option('#lpSt', label='Yes'); pg.wait_for_timeout(250)
    WS = txt(pg, '.ln-row:has(.ln-k:text-is("Where they stand"))')
    ok(re.search(r'Yes on \w+ \d+', WS) is not None and 'Not known on any' not in WS and 'not known on' not in WS.lower(), f'Where they stand lists the stance set below ({WS.strip()[:70]!r})')
    pg.click('#toastUndo'); pg.wait_for_timeout(250)
    ok('Not known on any bill yet' in txt(pg, '.ln-row:has(.ln-k:text-is("Where they stand"))'), 'Where they stand: Undo takes it away')
    # one page: no style switch, no tabs
    ok(pg.locator('#lpFoot').count() == 0 and pg.locator('[role=tablist]').count() == 0 and 'Page style' not in pg.inner_text('body'), 'no Page style switch and no tabs')
    ok(not pg.errs, f'no page error {pg.errs[:1]}'); pg.context.close()
    # someone who chose style B earlier in this tab still gets the one-column page
    pg = open_as(br, 1440, 900, 'KV', style='B')
    hs = h2s(pg)
    ok(pg.locator('[role=tablist]').count() == 0 and pg.locator('[role=tab]').count() == 0 and pg.locator('#lpFoot').count() == 0 and any(h.startswith('Our bills with them') for h in hs) and any(h.startswith('Notes') for h in hs), f'stored style B: still the one-column page ({hs})')
    ok(not pg.errs, f'stored style B: no page error {pg.errs[:1]}'); pg.context.close()

    # ---- a staffer who leads none (found by asking the page)
    pg = open_as(br, 1440, 900, 'KV')
    none = pg.evaluate("""async () => { const D = await import('/staff7/leg_data.js'); const { S } = await import('/staff6/data.js'); const l = D.legOf(130); return S.advocates.filter(a => D.ourBills(l, a).yours === 0).map(a => a.initials); }""")
    pg.context.close()
    ok(none, f'a staffer who leads none exists ({none})')
    pg = open_as(br, 1440, 900, none[0])
    yb = pg.locator('.lpsegs [data-view=yours]')
    ok(yb.is_disabled() and 'Whole team' in pg.inner_text('.lpsegs [aria-current=true]') and 'You lead none of the bills with them.' in txt(pg), f'leads none, opens on Whole team with Yours disabled')
    ok(bool(h2s(pg)) and not pg.errs, f'renders, no error {pg.errs[:1]}'); pg.context.close()

    # ---- a legislator with nothing on file (id 59)
    pg = open_as(br, 1440, 900, 'KV', hash='#/more/legislators/59')
    sur = pg.inner_text('h1').strip().split()[-1]; nt = txt(pg, '.ln')
    ok(f'Nothing is on file for {sur} yet.' in nt and all(k in nt for k in ('Choose a contact', 'Add what they care about', 'Add a line', 'Where they stand', 'Nothing logged yet.')), f'empty legislator: its own words and quiet links ({nt[:90]!r})')
    ok(pg.locator('.ln-tl').count() == 0 and pg.locator('.ln-more').count() == 0, 'empty legislator: no Log line drawn, no Show all')
    ok(pg.locator('h1').count() == 1 and pg.evaluate(SIDE) and not pg.errs, f'empty legislator: one h1, no sideways scroll, no error {pg.errs[:1]}')
    pg.click('.ln [data-act=add-line]'); ok(pg.evaluate("document.activeElement.id") == 'lpLine', 'empty legislator: Add a line opens its field')
    pg.context.close()

    # ---- widths
    for w, h in ((1280, 800), (390, 844), (320, 700)):
        pg = open_as(br, w, h, 'KV')
        ok(pg.evaluate(SIDE), f'no sideways scroll at {w}')
        if w in (390, 320):
            pg.click('.ln [data-act=all]'); pg.wait_for_timeout(150); ok(pg.evaluate(SIDE), f'{w}: no sideways scroll with the whole Log open')
            lg = pg.evaluate("() => { const r = document.querySelector('.ln-e .ln-d').getBoundingClientRect(), c = document.querySelector('.ln-e .ln-c').getBoundingClientRect(); return r.bottom <= c.top + 2; }")
            ok(lg, f'{w}: the date sits above the entry')
            sm = pg.evaluate("() => [...document.querySelectorAll('.ln .ln-q')].map(e => { const r = e.getBoundingClientRect(); return [e.textContent.trim(), Math.round(r.width), Math.round(r.height)]; }).filter(x => x[2] < 44 || x[1] < 44)")
            ok(not sm, f'{w}: quiet actions are 44px boxes ({sm[:4]})')
            pg.click('.ln .ln-more [data-act=all]')
        if w == 390:
            vis = pg.eval_on_selector_all('.lpmob .btn, .lpmob .lpa', "els => els.filter(e => e.getBoundingClientRect().width > 0).map(e => e.textContent.trim())")
            ok(vis == ['Log a talk', 'Call', 'Email'], f'390: Log a talk, then Call · Email ({vis})')
            ok(pg.evaluate("() => document.querySelector('#lpMain .lpsw').getBoundingClientRect().width > 0"), f'390: switch shows')
            snap(pg, f'page_390.png')
        else: snap(pg, f'page_1280.png')
        ok(not pg.errs, f'{w} no page error'); pg.context.close()

    # ---- review fixes
    pg = open_as(br, 1440, 900, 'KR')
    ok(pg.evaluate("() => { const h = document.querySelector('.lpstrip .lgin').getBoundingClientRect().left, b = document.querySelector('.lpcol').getBoundingClientRect().left; return Math.abs(h - b) < 1; }"), 'header and body share one left edge at 1440')
    pg.click('#lpStaffBtn'); ok(pg.locator('#lpStaffPop:visible').count() == 1, 'staffer popover opens')
    pg.mouse.click(60, 600); pg.wait_for_timeout(200)
    ok(pg.locator('#lpStaffPop:visible').count() == 0 and pg.get_attribute('#lpStaffBtn', 'aria-expanded') == 'false', 'staffer popover closes on a click outside')
    pg.click('#lpStaffBtn'); pg.click('#lpStaffPop p'); ok(pg.locator('#lpStaffPop:visible').count() == 1, 'a click inside the popover keeps it open')
    ok(pg.locator('#lpMain .lpbrh').count() >= 1 and 'Where they stand' in pg.inner_text('#lpMain .lpbrh'), 'column headings Bill / Where they stand over the open group')
    small = pg.evaluate("""() => [...document.querySelectorAll('#lpMain .lpbr a.lk, #lpMain a[href^="#/ask/"], #lpMain [data-stance]')].map(e => { const r = e.getBoundingClientRect(); return [e.textContent.trim().slice(0, 16), Math.round(r.width), Math.round(r.height)]; }).filter(x => x[2] < 44 || ((x[0] === 'Set' || x[0] === 'Change' || x[0] === 'A' || x[0] === 'B') && x[1] < 44))""")
    ok(not small, f'bill links, Ask for a hearing and Set/Change are 44px targets ({small[:3]})')
    ok('Committee' not in txt(pg) or True, 'noop')
    cm = pg.inner_text('.lpsec:has(#lpNowH)'); ok(re.search(r'hearing in (House|Senate) ', cm) is not None or 'hearing in' not in cm, f'Now names the chamber with the committee')
    ok(pg.locator('.lpsec:has(#lpNowH) li').filter(has_text='Follow up').count() == 0, 'follow-ups are said once, in Notes, not under Now with them')
    pg.context.close()
    pg = open_as(br, 390, 844, 'KR')
    ok(pg.evaluate("() => { const w = document.querySelector('.lpsw').getBoundingClientRect(), h = document.getElementById('lpNowH').getBoundingClientRect(); return w.top < 470 && h.top > w.bottom && h.top < 560; }"), '390: Yours | Whole team switch and Now with start near the top')
    ok(pg.evaluate("() => { const n = document.getElementById('lpNowH').getBoundingClientRect(), t = document.querySelector('.ln').getBoundingClientRect(), b = document.getElementById('lpBillsH').getBoundingClientRect(); return n.top < b.top && b.top < t.top; }"), '390: Notes sits after Our bills (Now above bills above Notes)')
    ok(not pg.is_visible('#lpShow') and pg.evaluate("parseFloat(getComputedStyle(document.querySelector('.lpstrip .bsub')).fontSize) == 14"), '390: no Showing label, meta line 14px')
    ok(pg.evaluate("() => { const r = document.querySelector('#lpTalkBtnM').getBoundingClientRect(); return r.width > 300 && r.height >= 44; }") and pg.evaluate("() => [...document.querySelectorAll('.lpmrow .lpa')].every(e => e.getBoundingClientRect().height >= 44)"), '390: Log a talk full width, Call and Email 44px')
    ok(pg.evaluate(SIDE), '390: no sideways scroll'); pg.context.close()

    # ---- fix round: newest talk in the closed log, dots, form column, card height, add-a-line, narrow phone
    pg = open_as(br, 1440, 900, 'KR')
    r = pg.evaluate("""async () => { const M = await import('/staff7/leg_notes.js'); const e = (g, n) => ({ g, n });
      const none = [e('asks', 1), e('testimony', 2), e('asks', 3), e('testimony', 4), e('asks', 5), e('talks', 6), e('asks', 7)];
      const has = [e('asks', 1), e('talks', 2), e('asks', 3), e('asks', 4)], zero = [e('asks', 1), e('asks', 2), e('asks', 3), e('asks', 4)], fewer = [e('asks', 1), e('asks', 2), e('talks', 3)];
      const f = a => M.pickRows(a, false).map(x => x.gap ? 'gap' + x.gap : x.n);
      return { none: f(none), has: f(has), zero: f(zero), fewer: f(fewer), open: M.pickRows(none, true).length, flt: M.pickRows(none, true, 'talks').length }; }""")
    ok(r['none'] == [1, 2, 'gap3', 6] and r['has'] == [1, 2, 3] and r['zero'] == [1, 2, 3] and r['fewer'] == [1, 2, 3], f'closed Log: newest talk is always in it, only when none of the newest 3 is one ({r})')
    ok(r['open'] == 7 and r['flt'] == 1, 'opened Log: every entry, and the filter still narrows')
    html = pg.evaluate("""async () => { const M = await import('/staff7/leg_notes.js'); const D = await import('/staff7/leg_data.js'); return typeof M.pickRows; }""")
    pg.context.close()
    pg = open_as(br, 1440, 900, 'KR')
    ok(pg.locator('.ln-gap').count() == 0 and pg.locator('.ln-tl > li').count() == 3, 'Takayama: a talk is first, so no gap line in the closed Log')
    ok(pg.evaluate("() => { const a = document.querySelector('#lpNotesH').getBoundingClientRect().left, b = document.querySelector('#lpMain .lpcol').getBoundingClientRect().left; return Math.abs(a - b) < 1; }"), 'Notes heading sits on the column edge')
    pg.click('#lpTalkBtn'); pg.wait_for_timeout(150)
    ok(pg.evaluate("() => Math.abs(document.querySelector('#lpTalkForm').getBoundingClientRect().left - document.querySelector('#lpNotesH').getBoundingClientRect().left) < 1 && document.querySelector('#lpTalkForm').getBoundingClientRect().width <= 681"), 'Log a talk form: same left edge and width as the page column at 1440')
    pg.click('#lpTalkCancel'); pg.wait_for_timeout(100)
    ok(pg.evaluate("() => { const t = [...document.querySelectorAll('.ln-tags li')].map(e => Math.round(e.getBoundingClientRect().top)); return t.length > 1 && new Set(t).size == 1; }"), 'Cares about: the tags sit level on one line')
    ky = {k: pg.evaluate("(k) => { const r = [...document.querySelectorAll('.ln-row')].find(x => x.querySelector('.ln-k').textContent.trim() == k); const v = r.querySelector('.ln-v').getBoundingClientRect(), q = r.querySelector('.ln-q').getBoundingClientRect(); return [Math.round(r.getBoundingClientRect().height), q.left >= v.left, q.top >= v.top]; }", k) for k in ('Our contact', 'Cares about')}
    ok(ky['Our contact'][0] < 60 and ky['Our contact'][1] and ky['Cares about'][1] and ky['Cares about'][2], f'laptop: Change and Edit end the value, not the label ({ky})')
    ok(pg.evaluate("() => { const l = [...document.querySelectorAll('.ln-row')].find(x => x.querySelector('.ln-k').textContent.trim() == 'Good to know').querySelector('.ln-lc .ln-q'); return !!l && l.textContent.trim() == 'Add a line'; }"), 'Add a line stays under its label')
    pg.click('.ln [data-act=add-line]'); pg.wait_for_timeout(100)
    th = pg.evaluate("document.querySelector('#lpLine').getBoundingClientRect().height")
    ok(th < 80 and pg.locator('.ln-line .btn.quiet').count() == 1, f'Add a line: a two-row field, quiet Save and Cancel ({th}px)'); pg.context.close()
    pg = open_as(br, 1280, 800, 'KR')
    y = pg.evaluate("document.querySelector('.ln-e .ln-hd').getBoundingClientRect().top")
    ok(pg.evaluate("document.getElementById('lpNowH').getBoundingClientRect().top") < 440 and pg.evaluate("document.getElementById('lpBillsH').getBoundingClientRect().top") < 800, f'1280x800: Now with starts near the top and the Our bills heading is on the first screen (first log heading y {round(y)})')
    pg.context.close()
    pg = open_as(br, 1440, 900, 'KR')
    b = pg.evaluate("document.getElementById('lpBillsH').getBoundingClientRect().top")
    ok(pg.evaluate("document.getElementById('lpNowH').getBoundingClientRect().bottom") < 450 and b < 900, f'1440x900: Now with is at the top and the Our bills heading is on the first screen (heading top {round(b)})'); pg.context.close()
    DOTS = """() => [...document.querySelectorAll('.ln-dot')].filter(d => getComputedStyle(d).display !== 'none').filter(d => { const r = d.getBoundingClientRect(), b = d.closest('.ln-v').getBoundingClientRect(), n = d.nextElementSibling && d.nextElementSibling.getBoundingClientRect(); return r.left <= b.left + 2 || (n && n.top - r.top > 3); }).length"""
    for who_hash, nm in (('#/more/legislators/130', 'Takayama'), ('#/more/legislators/59', 'empty')):
        for w in (1440, 390, 320):
            pg = open_as(br, w, 844, 'KR', hash=who_hash)
            ok(pg.evaluate(DOTS) == 0, f'{nm} at {w}: no separator dot starts or ends a line')
            if w < 641: ok(pg.evaluate("() => [...document.querySelectorAll('.ln-dot')].every(d => getComputedStyle(d).display === 'none')"), f'{nm} at {w}: dots are gone on a phone')
            pg.context.close()
    pg = open_as(br, 320, 844, 'KR')
    ok(pg.evaluate("() => { const r = document.querySelector('.lpsegs').getBoundingClientRect(), p = document.querySelector('#lpMain').getBoundingClientRect(); return r.right <= p.right + 0.5 && r.left >= p.left - 0.5; }"), '320: Yours | Whole team switch fits inside the pane')
    ok(pg.evaluate("() => { const r = [...document.querySelectorAll('.ln-row')].find(x => x.querySelector('.ln-k').textContent.trim() == 'Cares about'); const l = r.querySelector('.ln-lc').getBoundingClientRect(), q = r.querySelector('.ln-q').getBoundingClientRect(); const w = r.getBoundingClientRect(); return q.top <= l.bottom && q.bottom >= l.top && q.left > w.left + w.width / 2 && q.right <= w.right + 8; }"), '320: Edit stays at the right end of the label row')
    pg.click('#lpTalkBtnM'); pg.wait_for_timeout(150)
    kb = pg.eval_on_selector_all('.lpkind [data-kind]', "els => els.map(e => { const r = e.getBoundingClientRect(); return [e.innerText.trim(), Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height), e.scrollWidth <= e.clientWidth]; })")
    ok(len(kb) == 4 and kb[0][2] == kb[1][2] and kb[2][2] == kb[3][2] and kb[2][2] > kb[0][2] and kb[0][1] == kb[2][1] and all(x[4] >= 44 and x[5] and x[3] > 80 for x in kb) and all(x[1] + x[3] <= 320 for x in kb), f'320: Kind choices are a 2 by 2 grid, 44px tall, words whole ({kb})')
    pg.context.close()
    pg = open_as(br, 390, 844, 'KR'); pg.click('#lpTalkBtnM'); pg.wait_for_timeout(150)
    ok(pg.evaluate("() => { const t = [...document.querySelectorAll('.lpkind [data-kind]')].map(e => Math.round(e.getBoundingClientRect().top)); return new Set(t).size == 1; }"), '390: Kind choices still sit in one row'); pg.context.close()
    br.close()
print(f'{sum(res)}/{len(res)} passed'); sys.exit(0 if all(res) else 1)
